class PaymentError(Exception):
    pass


class PaymentGateway:
    def charge(self, amount: int) -> str:
        """Return a receipt id; raise PaymentError on failure."""
        raise NotImplementedError


class SandboxGateway(PaymentGateway):
    def charge(self, amount: int) -> str | None:
        if amount > 1_000_000:
            return None
        return "sandbox-receipt"


def checkout(gateway: PaymentGateway, amount: int) -> str:
    try:
        receipt = gateway.charge(amount)
    except PaymentError:
        return "payment failed"
    return f"paid, receipt {receipt.upper()}"

def shipping_fee(method: str, weight: float) -> float:
    if method == "standard":
        return 15_000 + weight * 2_000
    elif method == "express":
        return 30_000 + weight * 3_000
    elif method == "drone":
        return 50_000
    raise ValueError(method)

