from fastapi import HTTPException

from application.ports import OrderRepository


class CancelOrder:
    def __init__(self, orders: OrderRepository) -> None:
        self._orders = orders

    def execute(self, order_id: int) -> None:
        order = self._orders.get(order_id)
        if order is None:
            raise HTTPException(status_code=404, detail="Order not found")
        order.cancel()
        self._orders.save(order)

class SqlOrderRepository:
    def __init__(self, session: Session) -> None:
        self._session = session

    def add(self, order: Order) -> None:
        self._session.add(order)
        self._session.commit()


class SqlStockRepository:
    def __init__(self, session: Session) -> None:
        self._session = session

    def reserve(self, sku: str, qty: int) -> None:
        item = self._session.get(StockItem, sku)
        item.reserve(qty)  # raises OutOfStock
        self._session.commit()


class PlaceOrder:
    def __init__(self, orders, stock) -> None:
        self._orders, self._stock = orders, stock

    def execute(self, order: Order) -> None:
        self._orders.add(order)
        for line in order.lines:
            self._stock.reserve(line.sku, line.qty)
